using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using PetShop.Web.Data;using PetShop.Web.Services;
namespace PetShop.Web.Pages.Products;
public sealed class SaleModel(ApplicationDbContext db,OrderService orders,UserManager<IdentityUser> users):PageModel
{
 [BindProperty]public InputModel Input{get;set;}=new(){RequestId=Guid.NewGuid().ToString("N")};public List<SelectListItem> ProductOptions{get;private set;}=[];public List<SelectListItem> MemberOptions{get;private set;}=[];public List<SelectListItem> Methods{get;}=[new("现金","1"),new("微信","2"),new("支付宝","3"),new("银行卡","4"),new("其他","5")];
 public async Task OnGetAsync(Guid? productId=null){await LoadAsync();if(productId.HasValue&&ProductOptions.Any(x=>x.Value==productId.Value.ToString()))Input.ProductId=productId.Value;}
 public async Task<IActionResult> OnPostAsync(){if(!ModelState.IsValid){await LoadAsync();return Page();}var user=await users.GetUserAsync(User);try{Guid? card=null;Guid? customer=null;if(Input.MemberCardId.HasValue){card=Input.MemberCardId;customer=await db.MemberCards.Where(x=>x.Id==card).Select(x=>(Guid?)x.CustomerId).SingleOrDefaultAsync();}var result=await orders.SellProductAsync(Input.ProductId,Input.Quantity,customer,card,Input.Method,Input.RequestId,user!.Id);TempData["Success"]=$"收银成功：会员余额支付 ¥{result.PrincipalPaid+result.BonusPaid:F2}，外部收款 ¥{result.ExternalPaid:F2}。";return RedirectToPage("Index");}catch(Exception ex){ModelState.AddModelError("",ex.Message);Input.RequestId=Guid.NewGuid().ToString("N");await LoadAsync();return Page();}}
 private async Task LoadAsync(){var ps=await db.Products.AsNoTracking().Where(x=>x.IsActive&&x.StockQuantity>0).OrderBy(x=>x.Name).ToListAsync();ProductOptions=ps.Select(x=>new SelectListItem($"{x.Name} · ¥{x.SalePrice:F2} · 库存 {x.StockQuantity:0.##}",x.Id.ToString())).ToList();var ms=await db.MemberCards.AsNoTracking().Include(x=>x.Customer).Where(x=>x.IsActive).OrderBy(x=>x.Customer.Name).ToListAsync();MemberOptions=ms.Select(x=>new SelectListItem($"{x.Customer.Name} · {x.Customer.Phone} · 余额 ¥{x.PrincipalBalance+x.BonusBalance:F2}",x.Id.ToString())).ToList();}
 public sealed class InputModel{[Required]public Guid ProductId{get;set;}[Range(0.01,999999)]public decimal Quantity{get;set;}=1;public Guid? MemberCardId{get;set;}public PaymentMethod Method{get;set;}=PaymentMethod.Cash;[Required]public string RequestId{get;set;}="";}
}
